import asyncio

from alembic import context

from app.core.settings import Settings
from app.db.base import Base
from app.db.models import TaskModel, WorkspaceModel  # noqa: F401 -- register metadata
from app.db.session import create_engine


def include_object(object_, name, type_, reflected, compare_to):
    # Tables outside this metadata are not candidates for autogenerated DROP TABLE.
    return not (type_ == "table" and reflected and compare_to is None)


def run_migrations(connection):
    context.configure(
        connection=connection,
        target_metadata=Base.metadata,
        include_object=include_object,
        compare_type=True,
    )
    with context.begin_transaction():
        context.run_migrations()


async def run_async_migrations():
    engine = create_engine(Settings())
    try:
        async with engine.connect() as connection:
            await connection.run_sync(run_migrations)
    finally:
        await engine.dispose()


if context.is_offline_mode():
    raise RuntimeError("Offline migrations are not configured")
asyncio.run(run_async_migrations())
